def main(原始分数表: list[dict], 互评权重: float, 评审权重: float, 项目类别: str) -> dict:
    结果 = []
    提示 = []
    for 项 in (原始分数表 or []):
        名 = 项.get("项目名称", "")
        评分 = 项.get("各部门评分", {}) or {}
        if not 评分:
            提示.append("「" + 名 + "」无有效评分，跳过")
            continue
        互评 = {d: f for d, f in 评分.items() if "领导" not in d and "评审" not in d}
        评审 = {d: f for d, f in 评分.items() if "领导" in d or "评审" in d}

        def 去极值均值(分们: dict) -> float:
            vs = sorted(分们.values())
            if len(vs) >= 3:
                vs = vs[1:-1]
            return round(sum(vs) / len(vs), 2) if vs else 0.0

        互评均 = 去极值均值(互评)
        评审均 = 去极值均值(评审)
        if 评审均 > 0 and 互评均 > 0:
            总 = round(互评均 * 互评权重 + 评审均 * 评审权重, 2)
            构成 = "互评" + str(互评均) + "×" + str(互评权重) + "+评审" + str(评审均) + "×" + str(评审权重)
        elif 互评均 > 0:
            总 = 互评均
            构成 = "仅有互评分" + str(互评均) + "（未识别评审分，未加权）"
            提示.append("「" + 名 + "」未识别到评审分，按互评分计")
        else:
            总 = 评审均
            构成 = "仅有评审分" + str(评审均)
        结果.append({"项目名称": 名, "总成绩": 总, "计算构成": 构成, "互评均值": 互评均, "评审均值": 评审均})

    结果.sort(key=lambda x: -x["总成绩"])
    n = len(结果)
    类别 = (项目类别 or "科技").strip()
    比例 = 0.3 if "管理" in 类别 else 0.6
    推荐数 = max(1, round(n * 比例)) if n else 0
    for i, r in enumerate(结果):
        r["排名"] = i + 1
        r["是否建议推荐"] = i < 推荐数

    排序表 = "\n".join(
        str(r["排名"]) + ". " + r["项目名称"] + " —— " + str(r["总成绩"]) + "分（" + r["计算构成"] + "）" + ("✅建议推荐" if r["是否建议推荐"] else "")
        for r in 结果
    )
    报告 = "共" + str(n) + "个项目完成计算（" + 类别 + "类，推荐比例" + str(int(比例 * 100)) + "%，建议推荐" + str(推荐数) + "个）\n" + 排序表
    if 提示:
        报告 += "\n\n⚠️注意：\n" + "\n".join(提示)
    return {"score_rank_table": 结果, "score_report": 报告, "project_count": n, "recommend_count": 推荐数}

def main(打分文件列表: list[dict]) -> dict:
    import re

    文本们 = []
    for 项 in (打分文件列表 or []):
        if isinstance(项, dict):
            文本们.append((str(项.get("文件名", 项.get("name", ""))), str(项.get("内容", 项.get("content", 项.get("text", ""))))))
        else:
            文本们.append(("", str(项)))

    项目分数 = {}

    def 记分(部门: str, 项目名: str, 分: float):
        项目名 = 项目名.strip()
        if not 项目名 or len(项目名) < 3:
            return
        项目分数.setdefault(项目名, {})[部门 or "未知部门"] = 分

    for 部门, 文本 in 文本们:
        行们 = (文本 or "").replace("\r", "").split("\n")
        部门名 = ""
        m = re.search(r"(生产技术部|综合部|通信一部|通信二部|通信三部|信号一部|信号二部|信号三部|弱电一部|弱电二部|机电一部|机电二部)", 部门 + (文本 or "")[:200])
        if m:
            部门名 = m.group(1)
        for 行 in 行们:
            行 = 行.strip()
            if not 行:
                continue
            cells = re.split(r"[\t|,，]", 行)
            if len(cells) >= 3:
                名 = cells[1].strip() if len(cells) > 1 else ""
                数 = [c for c in cells if re.fullmatch(r"\d{2}(?:\.\d+)?", c.strip())]
                if 名 and len(名) >= 4 and 数:
                    分 = float(数[-1])
                    if 60 <= 分 <= 100:
                        记分(部门名, 名, 分)
                    continue
            m2 = re.search(r"([\u4e00-\u9fa5A-Za-z0-9·、]{6,40})(?:项目)?\s*[:：]?\s*(\d{2}(?:\.\d+)?)\s*分?", 行)
            if m2:
                分 = float(m2.group(2))
                if 60 <= 分 <= 100:
                    记分(部门名, m2.group(1), 分)

    if not 项目分数:
        return {"raw_score_table": [], "parse_note": "未能从打分表文件中解析出评分数据。请确认：1)文件为各部门对参评项目的打分表；2)含项目名称与分数。", "dept_count": 0}

    表 = [{"项目名称": k, "各部门评分": v, "评委数": len(v)} for k, v in 项目分数.items()]
    return {
        "raw_score_table": 表,
        "dept_count": len({d for _, v in 项目分数.items() for d in v}),
        "parse_note": "共解析 " + str(len(表)) + " 个项目、" + str(sum(x["评委数"] for x in 表)) + " 条部门评分。已按项目聚合，等待下一步计算。",
    }

def main(提取文本列表: list[object]) -> dict:
    import re

    def 项目名提取(文本: str) -> str:
        候选 = re.findall(r"(?:项目名称|成果主题|主题)[:：]\s*([^\n，。；]{4,40})", 文本 or "")
        if 候选:
            return 候选[0].strip()
        行 = [l.strip() for l in (文本 or "").split("\n") if 4 <= len(l.strip()) <= 40]
        return 行[0] if 行 else "未识别项目"

    项目列表 = []
    for 项 in (提取文本列表 or []):
        if isinstance(项, dict):
            文件名 = str(项.get("文件名", 项.get("name", "")))
            正文 = str(项.get("内容", 项.get("content", 项.get("text", ""))))
        else:
            文件名, 正文 = "", str(项)
        if not 正文.strip():
            continue
        项目列表.append({"文件名": 文件名, "项目名称": 项目名提取(正文), "正文": 正文})

    关键词 = 项目列表[0]["项目名称"] if 项目列表 else ""
    说明 = "解析出项目 " + str(len(项目列表)) + " 个" if 项目列表 else "未从申报文件中解析出有效项目内容，请检查上传文件。"
    return {
        "projects": 项目列表,
        "project_count": len(项目列表),
        "mcp_keyword": 关键词,
        "parse_note": 说明,
    }

