def main(projects: list[dict], mcp_content: list[dict], mcp_is_error: float) -> dict:
    import re

    def 相似度(甲: str, 乙: str) -> float:
        甲词 = set(re.findall(r"[\u4e00-\u9fa5a-zA-Z0-9]{2,}", 甲))
        乙词 = set(re.findall(r"[\u4e00-\u9fa5a-zA-Z0-9]{2,}", 乙))
        if not 甲词 or not 乙词:
            return 0.0
        return len(甲词 & 乙词) / max(1, min(len(甲词), len(乙词)))

    if mcp_is_error or not mcp_content:
        报告 = "MCP查重服务返回异常（is_error=" + str(mcp_is_error) + "），本次未完成查重。\n建议：确认本机8902服务已启动后重试，或以『旁路』模式重新提交走平台项目库比对+人工确认。"
        return {"dup_report": 报告, "clean_projects": [], "dup_projects": [], "dup_flag_list": "MCP异常，未查重", "project_count": len(projects or []), "mcp_status": "error"}

    库内项目 = []
    for e in (mcp_content or []):
        if not isinstance(e, dict):
            continue
        名称 = str(e.get("项目名称", e.get("name", e.get("title", ""))))
        摘要 = str(e.get("关键词", e.get("keywords", ""))) + " " + str(e.get("内容", e.get("content", e.get("摘要", ""))))[:2000]
        if 名称:
            库内项目.append({"项目名称": 名称, "关键词": 摘要[:1500]})

    阈值 = 0.62
    可入库, 重复项目, 标记行 = [], [], []
    for p in (projects or []):
        名称 = p.get("项目名称", "")
        摘要 = 名称 + " " + str(p.get("正文", ""))[:3000]
        最佳匹配, 最佳分 = None, 0.0
        for b in 库内项目:
            分 = 相似度(摘要, b["项目名称"] + " " + b["关键词"])
            if 分 > 最佳分:
                最佳分, 最佳匹配 = 分, b
        if 最佳分 >= 阈值 and 最佳匹配 is not None:
            重复项目.append({"项目名称": 名称, "相似度": round(最佳分 * 100), "疑似重复于": 最佳匹配["项目名称"]})
            标记行.append("【重复风险】" + 名称 + " —— 与库内「" + 最佳匹配["项目名称"] + "」相似度约" + str(round(最佳分 * 100)) + "%")
        else:
            可入库.append({"项目名称": 名称, "摘要": str(p.get("正文", ""))[:1500]})

    报告 = "查重结论（正式·MCP查重系统库）：共解析项目 " + str(len(projects or [])) + " 个；无重复风险 " + str(len(可入库)) + " 个；存在重复风险 " + str(len(重复项目)) + " 个。\n"
    if 标记行:
        报告 += "重复标记：\n" + "\n".join(标记行)
    状态 = "ok，命中库内候选 " + str(len(库内项目)) + " 条"
    return {"dup_report": 报告, "clean_projects": 可入库, "dup_projects": 重复项目, "dup_flag_list": "\n".join(标记行) or "无重复风险", "project_count": len(projects or []), "mcp_status": 状态}

def main(projects: list[dict], es_result: str) -> dict:
