                    库.append({"项目名称": 名称, "关键词": 摘要})
            elif e:
                库.append({"项目名称": str(e)[:60], "关键词": str(e)[:1500]})
        return 库

    库内项目 = 取库内(es_result)
    阈值 = 0.55
    可入库, 重复项目, 标记行 = [], [], []
