            标记行.append("【疑似重复·待人工确认】" + 名称 + " —— 与库内「" + 最佳匹配["项目名称"] + "」相似度约" + str(round(最佳分 * 100)) + "%")
        else:
            可入库.append({"项目名称": 名称, "摘要": str(p.get("正文", ""))[:1500]})

    报告 = "查重结论（降级模式·平台项目库关键词检索）：共解析项目 " + str(len(projects or [])) + " 个；无重复风险 " + str(len(可入库)) + " 个；疑似重复 " + str(len(重复项目)) + " 个。\n"
    报告 += "【重要】当前为MCP不可用的降级查重，仅基于关键词近似比对，结果仅供参考，重复判定必须经人工确认后方可入库。\n"
    if 标记行:
        报告 += "疑似重复标记：\n" + "\n".join(标记行)
    状态 = "降级检索命中候选 " + str(len(库内项目)) + " 条"
    return {"dup_report": 报告, "clean_projects": 可入库, "dup_projects": 重复项目, "dup_flag_list": "\n".join(标记行) or "无疑似重复", "project_count": len(projects or []), "mcp_status": 状态}

